package com.icewright.generated.service;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.icewright.generated.config.Settings;
import jakarta.annotation.PreDestroy;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * 非实时交互：msgid 幂等合并 + 异步处理 + 文件回推。
 *
 * <p>契约（与设计文档第 8 节一致，三栈同形）：入站消息带 msgid 时按
 * {@code msg:{session_id}:{msgid}} 登记幂等记录，重发不重复处理；异步任务结果文件落盘
 * data/files/（默认本地实现，可整层替换：saveFile/loadFile 即接口），Redis 只存
 * 状态+文件标识映射（带 TTL）；取回凭 会话+msgid 双段键，严禁裸 msgid 全局键；
 * 配 IW_CALLBACK_URL 则完成时推送一次（尽力而为，失败不影响轮询取回）。</p>
 *
 * @author IceWright builder
 */
@Service
public class AsyncMessageService {

    private static final int MSG_TTL_SECONDS = 3600;
    private static final Path FILES_DIR = Path.of("data", "files");
    private static final Duration CALLBACK_TIMEOUT = Duration.ofSeconds(5);

    private final ChatService chatService;
    private final SessionService sessionService;
    private final ObjectMapper mapper = new ObjectMapper();
    /** 小容量固定线程池：异步任务并行的默认实现，客户有编排系统可替换本服务执行器。 */
    private final ExecutorService pool = Executors.newFixedThreadPool(4);
    private final HttpClient http = HttpClient.newBuilder().connectTimeout(CALLBACK_TIMEOUT).build();

    public AsyncMessageService(ChatService chatService, SessionService sessionService) {
        this.chatService = chatService;
        this.sessionService = sessionService;
    }

    /**
     * 同步 /chat 的 msgid 支路：已处理过直接回放原回执（不重复处理、不重复副作用）。
     *
     * @param sessionId 会话标识
     * @param msgid 消息标识，空则退化为普通同步对话
     * @param message 用户消息
     * @param language 语言
     * @return 线格式回执（session_id/reply/matched_rules/language）
     */
    public Map<String, Object> answerIdempotent(String sessionId, String msgid, String message, String language) {
        if (msgid == null || msgid.isEmpty()) {
            return toWire(chatService.answer(sessionId, message, language));
        }
        Map<String, Object> record = sessionService.getRecord(msgSuffix(sessionId, msgid));
        if (record != null && "ready".equals(record.get("status")) && record.get("reply") instanceof Map<?, ?> reply) {
            @SuppressWarnings("unchecked")
            Map<String, Object> cached = (Map<String, Object>) reply;
            return cached;
        }
        Map<String, Object> result = toWire(chatService.answer(sessionId, message, language));
        Map<String, Object> next = new LinkedHashMap<>();
        next.put("status", "ready");
        next.put("reply", result);
        next.put("files", List.of());
        sessionService.putRecord(msgSuffix(sessionId, msgid), next);
        return result;
    }

    /**
     * 受理异步请求：重复 msgid 幂等返回既有状态，不再投任务。
     *
     * @param sessionId 会话标识
     * @param msgid 消息标识，空则由服务端生成（回执中返回）
     * @param message 用户消息
     * @param language 语言
     * @return {msgid, status}
     */
    public Map<String, Object> acceptAsync(String sessionId, String msgid, String message, String language) {
        String mid = msgid == null || msgid.isEmpty() ? UUID.randomUUID().toString().replace("-", "") : msgid;
        Map<String, Object> record = sessionService.getRecord(msgSuffix(sessionId, mid));
        String status = record == null ? null : String.valueOf(record.get("status"));
        if (status == null) {
            Map<String, Object> accepted = new LinkedHashMap<>();
            accepted.put("status", "accepted");
            accepted.put("reply", null);
            accepted.put("files", List.of());
            sessionService.putRecord(msgSuffix(sessionId, mid), accepted);
            pool.submit(() -> run(sessionId, mid, message, language));
            status = "accepted";
        }
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("session_id", sessionId);
        out.put("msgid", mid);
        out.put("status", status);
        return out;
    }

    private void run(String sessionId, String msgid, String message, String language) {
        Map<String, Object> next = new LinkedHashMap<>();
        try {
            Map<String, Object> result = toWire(chatService.answer(sessionId, message, language));
            String fileId = saveFile(Map.of(
                "session_id", sessionId,
                "msgid", msgid,
                "reply", result.get("reply"),
                "matched_rules", result.get("matched_rules"),
                "language", result.get("language")));
            List<Map<String, Object>> files = List.of(
                Map.of("file_id", fileId, "name", "reply-" + msgid + ".json"));
            next.put("status", "ready");
            next.put("reply", result);
            next.put("files", files);
            sessionService.putRecord(msgSuffix(sessionId, msgid), next);
            callback(sessionId, msgid, files);
        } catch (RuntimeException | IOException e) {
            // 异步任务失败必须落状态，绝不留悬挂 accepted
            next.put("status", "failed");
            next.put("error", String.valueOf(e.getMessage()));
            next.put("files", List.of());
            sessionService.putRecord(msgSuffix(sessionId, msgid), next);
        }
    }

    private void callback(String sessionId, String msgid, List<Map<String, Object>> files) {
        if (Settings.CALLBACK_URL.isEmpty()) {
            return;
        }
        try {
            // webhook 携带同一 file_id，消费端按 msgid 幂等重放安全
            String payload = mapper.writeValueAsString(Map.of(
                "session_id", sessionId, "msgid", msgid, "files", files));
            HttpRequest request = HttpRequest.newBuilder(URI.create(Settings.CALLBACK_URL))
                .timeout(CALLBACK_TIMEOUT)
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(payload, StandardCharsets.UTF_8))
                .build();
            http.send(request, HttpResponse.BodyHandlers.discarding());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } catch (IOException e) {
            // 回调失败不影响轮询取回
        }
    }

    /**
     * 轮询视图：状态 + 可下载文件清单。
     *
     * @param sessionId 会话标识
     * @param msgid 消息标识
     * @return 视图；msgid 未登记（或已过 TTL）时 null
     */
    public Map<String, Object> filesView(String sessionId, String msgid) {
        Map<String, Object> record = sessionService.getRecord(msgSuffix(sessionId, msgid));
        if (record == null) {
            return null;
        }
        String status = String.valueOf(record.get("status"));
        List<Map<String, Object>> files = new ArrayList<>();
        if (record.get("files") instanceof List<?> rawFiles) {
            for (Object item : rawFiles) {
                if (item instanceof Map<?, ?> file) {
                    @SuppressWarnings("unchecked")
                    Map<String, Object> f = new LinkedHashMap<>((Map<String, Object>) file);
                    f.put("download_url", "/messages/" + msgid + "/files/" + f.get("file_id")
                        + "?session_id=" + sessionId);
                    files.add(f);
                }
            }
        }
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("session_id", sessionId);
        out.put("msgid", msgid);
        out.put("status", "accepted".equals(status) ? "pending" : status);
        out.put("files", files);
        return out;
    }

    /**
     * 结果文件落盘（默认实现=本地 data/files，换共享存储只改 saveFile/loadFile 这一层）。
     *
     * @param content 文件内容
     * @return 服务端生成的 file_id
     * @throws IOException 写盘失败
     */
    public String saveFile(Map<String, Object> content) throws IOException {
        String fileId = UUID.randomUUID().toString().replace("-", "");
        Files.createDirectories(FILES_DIR);
        Files.writeString(FILES_DIR.resolve(fileId + ".json"),
            mapper.writeValueAsString(content), StandardCharsets.UTF_8);
        return fileId;
    }

    /**
     * 按服务端生成的 file_id 取文件；只认 .json 快照，杜绝路径穿越。
     *
     * @param fileId 文件标识
     * @return 文件路径；不存在时 null
     */
    public Path loadFile(String fileId) {
        if (fileId == null || !fileId.matches("[A-Za-z0-9]+")) {
            return null;
        }
        Path path = FILES_DIR.resolve(fileId + ".json");
        return Files.exists(path) ? path : null;
    }

    private static String msgSuffix(String sessionId, String msgid) {
        return "msg:" + sessionId + ":" + msgid;
    }

    private static Map<String, Object> toWire(ChatService.Reply reply) {
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("session_id", reply.sessionId());
        out.put("reply", reply.reply());
        out.put("matched_rules", reply.matchedRules());
        out.put("language", reply.language());
        return out;
    }

    @PreDestroy
    public void shutdown() {
        pool.shutdown();
    }
}
